n        return Err(DocumentParseError { error: DocumentError::ResourceExhausted, diagnostic: XmlDiagnostic::default() });\n    }\n    if source.len() > vexel_xml::MAX_INPUT_BYTES {\n        return Err(DocumentParseError {\n            error: DocumentError::Limit,\n            diagnostic: XmlDiagnostic { category: XmlError::InputLimit, offset: vexel_xml::MAX_INPUT_BYTES },\n        });\n    }\n\n    let mut stream = XmlTokenStream::new(source, storage_limit).map_err(|_| DocumentParseError {\n        error: DocumentError::OutOfMemory,\n        diagnostic: XmlDiagnostic::default(),\n    })?;\n    if stream.token_storage_bytes() > storage_limit\n        || stream.open_name_storage_bytes() > MAX_OPEN_NAME_BYTES\n    {\n        return Err(DocumentParseError { error: DocumentError::OutOfMemory, diagnostic: XmlDiagnostic::default() });\n    }\n    let status = loop {\n        let status = stream.step(STEP_BYTES, false);\n        if stream.token_storage_bytes() > storage_limit\n            || stream.open_name_storage_bytes() > MAX_OPEN_NAME_BYTES\n        {\n            return Err(DocumentParseError { error: DocumentError::OutOfMemory, diagnostic: stream.result().diagnostic });\n        }\n        if status != StreamStatus::Ok { break status; }\n    };\n    let result = stream.result();\n    if status != StreamStatus::Complete || result.diagnostic.category != XmlError::None {\n        let error = match result.diagnostic.category {\n            XmlError::InputLimit | XmlError::NodeLimit | XmlError::DepthLimit | XmlError::AttributeLimit\n            | XmlError::TextLimit => DocumentError::Limit,\n            XmlError::OutputExhausted => DocumentError::ResourceExhausted,\n            XmlError::None => DocumentError::OutOfMemory,\n            _ => DocumentError::Parse,\n        };\n        return Err(DocumentParseError { error, diagnostic: result.diagnostic });\n    }\n\n    if result.element_count == 0 || result.element_count > MAX_NODES || result.element_count > u32::MAX as usize\n        || result.attribute_count > vexel_xml::MAX_TOTAL_ATTRIBUTES\n        || checked_table_bytes::<Node>(result.element_count).is_none()\n        || checked_table_bytes::<Attribute>(result.attribute_count).is_none()\n    {\n        return Err(DocumentParseError { error: DocumentError::Limit, diagnostic: result.diagnostic });\n    }\n    let tokens = stream.take().ok_or(DocumentParseError {\n        error: DocumentError::Parse,\n        diagnostic: result.diagnostic,\n    })?;\n    if stream.token_storage_bytes() != 0 {\n        return Err(DocumentParseError { error: DocumentError::Parse, diagnostic: result.diagnostic });\n    }\n\n    let id = allocate_document_id().ok_or(DocumentParseError {\n        error: DocumentError::IdExhausted,\n        diagnostic: result.diagnostic,\n    })?;\n    let (nodes, attributes, root) = build_tables(source, &tokens, result.element_count, result.attribute_count)\n        .map_err(|error| DocumentParseError { error, diagnostic: result.diagnostic })?;\n    Ok(DocumentModel::from_parts(source, id, nodes, attributes, Some(root)))\n}\n\nfn build_tables(\n    source: &[u8],\n    tokens: &[XmlToken],\n    node_count: usize,\n    attribute_count: usize,\n) -> Result<(Vec<Node>, Vec<Attribute>, u32), DocumentError> {\n    let mut nodes: Vec<Node> = Vec::new();\n    nodes.try_reserve_exact(node_count).map_err(|_| DocumentError::OutOfMemory)?;\n    if nodes.capacity() > MAX_NODES { return Err(DocumentError::OutOfMemory); }\n    let mut attributes: Vec<Attribute> = Vec::new();\n    attributes.try_reserve_exact(attribute_count).map_err(|_| DocumentError::OutOfMemory)?;\n    if attributes.capacity() > vexel_xml::MAX_TOTAL_ATTRIBUTES { return Err(DocumentError::OutOfMemory); }\n    let mut stack: Vec<u32> = Vec::new();\n    stack.try_reserve_exact(MAX_DEPTH).map_err(|_| DocumentError::OutOfMemory)?;\n    if stack.capacity() > MAX_DEPTH { return Err(DocumentError::OutOfMemory); }\n\n    let mut root = None;\n    let mut index = 0usize;\n    while index < tokens.len() {\n        let token = tokens[index];\n        match token.kind {\n            TokenKind::StartElement | TokenKind::EmptyElement => {\n                if nodes.len() >= node_count || nodes.len() >= MAX_NODES || nodes.len() >= u32::MAX as usize\n                    || token.name.slice(source).is_none() || checked_span(token.source, source).is_none()\n                {\n                    return Err(DocumentError::Parse);\n                }\n                let slot = u32::try_from(nodes.len()).map_err(|_| DocumentError::Limit)?;\n                let parent = stack.last().copied().unwrap_or(no_slot());\n                let depth = stack.len();\n                let mut node = Node {\n                    name: token.name,\n                    source: DocumentSourceSpan { offset: token.source.offset, length: token.source.length },\n                    first_attribute: attributes.len(),\n                    depth,\n                    parent,\n                    ..Node::default()\n                };\n                if parent != no_slot() {\n                    let parent_index = parent as usize;\n                    let parent_node = nodes.get(parent_index).ok_or(DocumentError::Parse)?;\n                    let previous_last = parent_node.last_child;\n                    if parent_node.first_child == no_slot() { nodes[parent_index].first_child = slot; }\n                    else {\n                        let previous = nodes.get_mut(previous_last as usize).ok_or(DocumentError::Parse)?;\n                        previous.next_sibling = slot;\n                    }\n                    nodes[parent_index].last_child = slot;\n                } else if parent == no_slot() {\n                    if root.replace(slot).is_some() { return Err(DocumentError::Parse); }\n                } else {\n                    return Err(DocumentError::Parse);\n                }\n\n                index += 1;\n                while let Some(attribute) = tokens.g